    /// Asserted edge kinds, declaration order. Derived edges are deliberately
    /// a separate enum: they live in a separate arena and the store must
    /// refuse to serialise them (62 §11.4) — a shared enum invites exactly
    /// that defect.
    #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
    pub enum EdgeKind {
        /// 11 §7.2.
        HasDevice,
        /// 11 §7.2. Standalone boxes have one.
        HasChassis,
        /// 11 §7.2.
        HasRedundancyGroup,
        /// 11 §7.2.
        HasInterface,
        /// 11 §7.2. The class is expanded at codegen (62 §6.2).
        HasUnit,
        /// 11 §7.2.
        HasAddress,
        /// 11 §7.2.
        HasVlan,
        /// 11 §7.2.
        HasRoutingInstance,
        /// 11 §7.2.
        HasStaticRoute,
        /// 11 §7.2.
        HasRoutingProtocol,
        /// 11 §7.2.
        HasAdjacency,
        /// 11 §7.2.
        HasZone,
        /// 11 §7.2.
        HasPolicySet,
        /// 11 §7.2.
        HasPolicy,
        /// 11 §7.2.
        HasAddressObject,
        /// 11 §7.2.
        HasApplication,
        /// 11 §7.2.
        HasNatRuleSet,
        /// 11 §7.2.
        HasNatRule,
        /// 11 §7.2 — crypto objects hang off Device, not off each other; the config tree writes
        /// them as independently deletable siblings. The chain between them is reference.
        HasIkeProposal,
        /// 11 §7.2.
        HasIkePolicy,
        /// 11 §7.2.
        HasIkeGateway,
        /// 11 §7.2.
        HasIpsecProposal,
        /// 11 §7.2.
        HasIpsecPolicy,
        /// 11 §7.2.
        HasIpsecVpn,
        /// 11 §7.2.
        HasTrafficSelector,
        /// 11 §7.2.
        HasFlowSettings,
        /// 11 §7.2.
        HasSystemSettings,
        /// 11 §7.2.
        HasNtpServer,
        /// 11 §7.2.
        HasSyslogTarget,
        /// 11 §7.2, amended by 19 §5.1: from widened to [Site, Premises] so a subscriber endpoint
        /// can be a labelled terminal at a street address with no Site node. Widening is minor.
        HasExternalPeer,
        /// 11 §7.2 — a Tunnel spans sites and is contained by the workspace root.
        HasTunnel,
        /// 19 §5.1.
        HasPremises,
        /// 19 §5.1 — the same kind set PortHost names.
        HasPort,
        /// 19 §5.1.
        HasPassiveNode,
        /// 19 §5.1 — root-level; a cable spans two premises and cannot be contained by one.
        HasCable,
        /// 19 §5.2.
        HasTenant,
        /// 19 §5.2.
        HasServiceType,
        /// 19 §5.2.
        HasService,
        /// 19 §5.2 — a service with no endpoint is not a service. The upper bound comes from
        /// ServiceType.endpoint_cardinality and is checked at L1, per service, not here.
        HasEndpoint,
        /// 19 §5.2.
        HasPath,
        /// 19 §5.2.
        HasSegment,
        /// ike gateway GW-B ike-policy IKE-POL (11 §7.3).
        UsesIkePolicy,
        /// ike policy IKE-POL proposals IKE-P1 / ipsec policy IPSEC-POL proposals IPSEC-P2.
        /// NOTE (form vs content): 11 §7.3 declares TWO rows named UsesProposal (IkePolicy ->
        /// IkeProposal and IpsecPolicy -> IpsecProposal); 62 §6.2 makes edge names unique across
        /// the file (schema.edge.duplicate — the WarpResolvesVia precedent), so the rows are merged
        /// here into one declaration. The merged from/to sets do not forbid the cross pairing
        /// IkePolicy -> IpsecProposal; that narrowing needs either a rename in 11 or an L0 rule.
        /// Defect to file per 62 §1.
        UsesProposal,
        /// The WAN unit IKE packets leave by — an edge to a unit, never a name
        /// field (11 §6.7's "single most valuable typing decision").
        ExternalInterface,
        /// ipsec vpn VPN-B ike gateway GW-B (11 §7.3).
        UsesIkeGateway,
        /// ipsec vpn VPN-B ike ipsec-policy IPSEC-POL (11 §7.3).
        UsesIpsecPolicy,
        /// bind-interface st0.0. in: 0..1 — two VPNs on one st0 unit is a validity error
        /// (11 §7.3). Required when mode == RouteBased, forbidden when PolicyBased — see
        /// constraints: ipsec-vpn.mode-binds-interface.
        BindsInterface,
        /// vpn-monitor source-interface reth1.0 (11 §7.3).
        MonitorSource,
        /// Inventory linkage; no vendor form (11 §7.3).
        PeerIs,
        /// No vendor form (11 §7.3).
        TunnelEndpoint,
        /// No vendor form (11 §7.3).
        TunnelPeer,
        /// zones security-zone VPN interfaces st0.0 (11 §7.5). The edge with fields —
        /// zone.host-inbound.ike-missing fires against this edge, not against a Zone.
        ZoneMember,
        /// Implicit in from-zone X to-zone Y (11 §7.3).
        InPolicySet,
        /// match source-address NAME (11 §7.3).
        MatchSource,
        /// match destination-address NAME (11 §7.3).
        MatchDestination,
        /// match application NAME (11 §7.3).
        MatchApplication,
        /// then permit tunnel ipsec-vpn NAME — policy-based VPN, legacy (11 §7.3).
        TunnelsVia,
        /// address-set NAME address MEMBER (11 §7.3). Nesting legal; cycles are an L0 validity
        /// error checked store-side on write with a union-find (11 §6.6) — not expressible in
        /// 62 §12.3's grammar, so no constraints: entry.
        Contains,
        /// 11 §7.3.
        ContainsApp,
        /// Zone address books (11 §7.3); the global book is the absence of this edge.
        InAddressBook,
        /// routing-instances NAME interface st0.0 (11 §7.3).
        InRoutingInstance,
        /// ether-options 802.3ad ae0 (11 §7.3).
        MemberOfAggregate,
        /// gigether-options redundant-parent reth0 (11 §7.3).
        MemberOfReth,
        /// redundant-ether-options redundancy-group 1 (11 §7.3). The required edge that earns the kind.
        InRedundancyGroup,
        /// interface-monitor ge-0/0/0 weight 255 (11 §7.3).
        MonitorsInterface,
        /// The owner's Membership (11 §7.3).
        VlanMember,
        /// IRB / SVI (11 §7.3).
        L3Interface,
        /// SUPERSEDED by Cable + Terminates (19 §3.8) and kept per 19 §7.5 — removal would be a
        /// major bump. Direction is normalised on write (smaller NodeId becomes from, 11 §7.4);
        /// consumers must never read meaning into the direction of a symmetric edge. The Cabled
        /// traversal is now a derived edge.
        Link,
        /// Out of day-one scope; the edge exists so there is a home (11 §7.3).
        PeersWith,
        /// 19 §5.1. in: 0..n IS the requirement — "several units at this address" becomes a count
        /// of in-edges, not a population scan.
        AtPremises,
        /// A cable end lands on a port, or on an external peer at the modelling
        /// horizon. 19 §5.1. A breakout is four cables sharing a near-end port,
        /// never a four-ended cable — hyperedges are unrepresentable, deliberately.
        Terminates,
        /// 19 §3.7 — from is [Interface] only, not InterfaceLike: reth/ae reach hardware through
        /// their members; st0 reaches nothing. Created by the user (a parser may not — R-L2);
        /// infer.port.occupies produces a suggestion, never a graph change. L0 constraint
        /// occupies.same-device holds the layer separation.
        Occupies,
        /// "These two holes are the same hole" (19 §5.1) — the ODF/panel/splitter/WDM traversal.
        /// Degree drives rendering and traversal: exactly one makes the panel transparent; more
        /// than one is a fan-out. The shipped symmetric example (62 §6.2).
        PassThrough,
        /// The type is an edge to a node, not an enum field (19 §4.2).
        OfType,
        /// 19 §5.2.
        PathFrom,
        /// 19 §5.2. A Boundary-terminated path may point at an ExternalPeer or a Demarc endpoint.
        PathTo,
        /// 19 §4.4, §5.2.
        AtLocation,
        /// 19 §4.4 — the class admits the four interface kinds; LogicalUnit because a UNI is
        /// frequently a tagged unit; PhysicalPort because a demarcation may be recorded before any
        /// configuration exists. Reference, so R-L1 holds — deleting a service never deletes a port.
        AttachesTo,
        /// 19 §5.2. Two-level bound: a concurrent write of two entry ports on one segment must
        /// converge rather than conflict, so the store bound relaxes and the L1 rule
        /// service.path.segment.multiple-entry patrols the excess (62 §6.2's requirement that the
        /// patrolling rule be named here).
        EntersAt,
        /// 19 §5.2. Same two-level bound as EntersAt; patrolled by
        /// service.path.segment.multiple-entry. A Boundary segment deliberately leaves this unset.
        ExitsAt,
        /// 19 §5.2, §6.7 — constrain, never freeze; honoured by resolve_warp.
        MustTraverse,
        /// ADR-0035. CONTAINMENT and not a reference, for one reason that decides it: `Graph::tombstone`
        /// takes the subtree, so removing a device takes its pin with it. A pin for a box that is gone
        /// is not a fact anybody asserted — the same argument `OP_ELEMENT_REMOVE` already makes about
        /// a chassis. `out: "0..1"` is what makes "two positions for one box" unrepresentable rather
        /// than merely unwritten.
        HasLayoutPin,
    }

