    /// `schema/enums/cable_end.yaml`.
    /// Which end of the cable a termination is. A is the endpoint with the lexicographically
    /// smaller NodeId (19 §3.4 — 11 §7.4's Link normalisation applied to Terminates), which
    /// makes Cable's tier-1 identity tuple ordered and deterministic.
    #[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
    pub enum CableEnd {
        A,
        B,
        /// The generated unknown arm (62 §7 rule 2) — carries the
        /// unrecognised token verbatim; what makes a new variant a minor
        /// bump an old client survives (62 §16.2).
        Unknown(String),
    }

    impl CableEnd {
        /// Declared tokens, declaration order.
        pub const DECLARED: [&'static str; 2] = [
            "a",
            "b",
        ];
        /// Neutral token → variant; anything undeclared lands in `Unknown`.
        pub fn from_token(token: &str) -> CableEnd {
            match token {
                "a" => CableEnd::A,
                "b" => CableEnd::B,
                other => CableEnd::Unknown(other.to_owned()),
            }
        }
        /// The neutral token (the carried one for `Unknown`).
        pub fn token(&self) -> &str {
            match self {
                CableEnd::A => "a",
                CableEnd::B => "b",
                CableEnd::Unknown(t) => t,
            }
        }
    }

